import{_ as p,r as s,o,c as l,e as n,a as i,s as c}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Views & Partials - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Partials","slug":"partials","link":"#partials","children":[{"level":3,"title":"Hint Partials","slug":"hint-partials","link":"#hint-partials","children":[]},{"level":3,"title":"Checking if Hints are Hidden","slug":"checking-if-hints-are-hidden","link":"#checking-if-hints-are-hidden","children":[]}]},{"level":2,"title":"Layouts and Child Layouts","slug":"layouts-and-child-layouts","link":"#layouts-and-child-layouts","children":[{"level":3,"title":"Form with Sidebar","slug":"form-with-sidebar","link":"#form-with-sidebar","children":[]}]}],"relativePath":"2.x/backend/views-partials.md","filePath":"2.x/backend/views-partials.md"}'),r={name:"2.x/backend/views-partials.md"};function d(u,a,h,k,g,m){const t=s("pre-heading"),e=s("post-heading");return o(),l("div",null,[n(t),a[0]||(a[0]=i("h1",null,"Views & Partials",-1)),n(e),a[1]||(a[1]=c(`<h2 id="partials"><a href="#partials" class="header-anchor">#</a> Partials</h2><p>Back-end partials are files with the extension <strong>htm</strong> that reside in the <a href="./controllers-ajax.html">controller&#39;s views</a> directory. The partial file names should start with the underscore: <em>_partial.htm</em>. Partials can be rendered from a back-end page or another partial. Use the controller&#39;s <code>makePartial</code> method to render a partial. The method takes two parameters - the partial name and the optional array of variables to pass to the partial. Example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;sidebar&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;showHeader&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="hint-partials"><a href="#hint-partials" class="header-anchor">#</a> Hint Partials</h3><p>You can render informative panels in the backend, called hints, that the user can hide. The first parameter should be a unique key for the purposes of remembering if the hint has been hidden or not. The second parameter is a reference to a partial view. The third parameter can be some extra view variables to pass to the partial, in addition to some hint properties.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeHintPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_hint_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;my_hint_partial&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;foo&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>You can also disable the ability to hide a hint by setting the key value to a null value. This hint will always be displayed:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeHintPartial</span><span class="token punctuation">(</span><span class="token constant">null</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;my_hint_partial&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>The following properties are available:</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>type</strong></td><td>Sets the color of the hint, supported types: danger, info, success, warning. Default: info.</td></tr><tr><td><strong>title</strong></td><td>Adds a title section to the hint.</td></tr><tr><td><strong>subtitle</strong></td><td>In addition to the title, adds a second line to the title section.</td></tr><tr><td><strong>icon</strong></td><td>In addition to the title, adds an icon to the title section.</td></tr></tbody></table></div><h3 id="checking-if-hints-are-hidden"><a href="#checking-if-hints-are-hidden" class="header-anchor">#</a> Checking if Hints are Hidden</h3><p>If you&#39;re using hints, you may find it useful to check if the user has hidden them. This is easily done using the <code>isBackendHintHidden</code> method. It takes a single parameter, and that&#39;s the unique key you specified in the original call to <code>makeHintPartial</code>. The method will return true if the hint was hidden, false otherwise:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">isBackendHintHidden</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_hint_key&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token comment">&lt;!-- Do something when the hint is hidden --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p><a id="oc-layouts-and-child-layouts"></a></p><h2 id="layouts-and-child-layouts"><a href="#layouts-and-child-layouts" class="header-anchor">#</a> Layouts and Child Layouts</h2><p>Back-end layouts reside in an optional <strong>layouts/</strong> directory of a plugin. A custom layout is set with the <code>$layout</code> property of the controller object. It defaults to the system layout called <code>default</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var string Layout to use for the view.
 */</span>
<span class="token keyword">public</span> <span class="token variable">$layout</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mycustomlayout&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Layouts also provide the option to attach custom CSS classes to the BODY tag. This can be set with the <code>$bodyClass</code> property of the controller.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var string Body CSS class to add to the layout.
 */</span>
<span class="token keyword">public</span> <span class="token variable">$bodyClass</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;compact-container&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>These body classes are available for the default layout:</p><ul><li><strong>compact-container</strong> - uses no padding on all sides.</li><li><strong>slim-container</strong> - uses no padding left and right.</li><li><strong>breadcrumb-flush</strong> - tells the page breadcrumb to sit flush against the element below.</li></ul><h3 id="form-with-sidebar"><a href="#form-with-sidebar" class="header-anchor">#</a> Form with Sidebar</h3><p>Layouts can also be used in the same way as partials, acting more like a global partial. The system provides an example of this called <code>form-with-sidebar</code> and demonstrates a novel way to implement a child layout structure.</p><p>Before using this layout style, ensure that your controller uses the body class <code>compact-container</code> by setting it in your controller&#39;s action method or constructor.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">bodyClass</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;compact-container&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>This layout uses two placeholders, a primary content area called <strong>form-contents</strong> and a complimentary sidebar called <strong>form-sidebar</strong>. Here is an example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">&lt;!-- Primary content --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-contents&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    Main content
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token comment">&lt;!-- Complimentary sidebar --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-sidebar&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    Side content
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token comment">&lt;!-- Layout execution --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;body&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span><span class="token operator">=&gt;</span><span class="token string single-quoted-string">&#39;layout stretch&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeLayout</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-with-sidebar&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>The layout is executed in the final section by overriding the <strong>body</strong> placeholder used by every back-end layout. It wraps everything with a <code>&lt;form /&gt;</code> HTML tag and renders the child layout called <strong>form-with-sidebar</strong>. This file is located in <code>modules\\backend\\layouts\\form-with-sidebar.htm</code>.</p>`,28))])}const b=p(r,[["render",d]]);export{f as __pageData,b as default};
